	var file := FileAccess.open(path, FileAccess.READ)
	if not check("file_open", file != null, "Impossibile aprire res://story/story_schema.json"):
		return

	var content: String = file.get_as_text()
	var data: Variant = JSON.parse_string(content)
	if not check("json_valid", data is Dictionary, "Il file story_schema.json deve contenere un oggetto JSON valido"):
		return

	var schema: Dictionary = data

	var scenes: Variant = schema.get("scenes")
	var valid_scenes: bool = scenes is Array and scenes.size() >= 3
	check("scenes_count", valid_scenes, "Lo schema deve contenere un array 'scenes' con almeno 3 scene")

	var scene_ids: Array[String] = []
	if scenes is Array:
		for sc in scenes:
			if sc is Dictionary and sc.has("id"):
				var id_str: String = String(sc["id"])
				if not id_str.is_empty():
					scene_ids.append(id_str)
	check("scenes_ids", scene_ids.size() >= 3, "Tutte le scene devono avere un campo 'id' non vuoto (trovati %d id)" % scene_ids.size())

	var endings: Variant = schema.get("endings")
	var valid_endings: bool = endings is Array and endings.size() >= 2
	check("endings_count", valid_endings, "Lo schema deve contenere un array 'endings' con almeno 2 finali")

	var ending_ids: Array[String] = []
	if endings is Array:
		for ed in endings:
			if ed is Dictionary and ed.has("id"):
				var ed_id: String = String(ed["id"])
				if not ed_id.is_empty() and not ending_ids.has(ed_id):
					ending_ids.append(ed_id)
	check("endings_ids", ending_ids.size() >= 2, "I finali devono avere 'id' distinti e non vuoti (trovati %d finali)" % ending_ids.size())

	var variables: Variant = schema.get("variables")
	var var_keys: Array = []
	if variables is Dictionary:
		var_keys = variables.keys()
	elif variables is Array:
		var_keys = variables
	check("variables_present", var_keys.size() >= 1, "Lo schema deve definire almeno una variabile in 'variables'")

	var branches: Variant = schema.get("branches", schema.get("choices"))
	var valid_branches: bool = branches is Array and branches.size() >= 1
	check("branches_present", valid_branches, "Lo schema deve contenere un array 'branches' con almeno un bivio")

	var branch_options_ok := false
	if branches is Array:
		for br in branches:
			if br is Dictionary and br.has("options"):
				var opts = br["options"]
				if opts is Array and opts.size() >= 2:
					branch_options_ok = true
					break
	check("branch_options", branch_options_ok, "Almeno un bivio deve contenere una lista 'options' con almeno 2 scelte")

	var conditions: Variant = schema.get("conditions")
	var condition_found := false
	var variable_used := false

	if conditions is Array and conditions.size() >= 1:
		for cond in conditions:
			if cond is Dictionary and cond.has("variable"):
				condition_found = true
				var vname: String = String(cond["variable"])
				if var_keys.has(vname):
					variable_used = true
					break

	if not variable_used and branches is Array:
		for br in branches:
			if br is Dictionary and br.has("options"):
				var opts = br["options"]
				if opts is Array:
					for opt in opts:
						if opt is Dictionary and opt.has("condition"):
							var cond = opt["condition"]
							if cond is Dictionary and cond.has("variable"):
								condition_found = true
								var vname: String = String(cond["variable"])
								if var_keys.has(vname):
									variable_used = true
									break

	check("condition_exists", condition_found, "Lo schema deve contenere almeno una condizione narrativa")
	check("variable_in_condition", variable_used, "La condizione deve verificare una delle variabili dichiarate in 'variables'")

	var all_valid_targets: Array[String] = []
	all_valid_targets.append_array(scene_ids)
	all_valid_targets.append_array(ending_ids)

	var targets_valid := true
	var invalid_target_name := ""
	if branches is Array:
		for br in branches:
			if br is Dictionary and br.has("options"):
				var opts = br["options"]
				if opts is Array:
					for opt in opts:
						if opt is Dictionary and opt.has("target"):
							var tname: String = String(opt["target"])
							if not all_valid_targets.has(tname):
								targets_valid = false
								invalid_target_name = tname
								break

	check("targets_valid", targets_valid, "Tutti i target delle scelte devono puntare a scene o finali esistenti (target sconosciuto: '%s')" % invalid_target_name)
